    first = first,
  }
end

function M.UnitCreated(civ, ownerId, unitId, x, y)
  return {
    event = "unit_created",
    turn = civ.turn(),
    civ = civ.civName(ownerId),
    unit = civ.unitType(ownerId, unitId),
