    event = "reformation_added",
    turn = civ.turn(),
    civ = civ.civName(playerId),
    religion = civ.religionName(religionId),
    belief = civ.beliefType(beliefId),
  }
end

function M.sessionStarted(civ)
  local record = civ.gameSettings()
  record.event = "session_started"
  record.turn = civ.turn()
  record.players = civ.playerRoster()
  return record
end

return M
end)

register("src.logger", function()
-- Wires extractors to GameEvents hooks and streams encoded records
-- to a sink. A logging failure must never escape into the game, so
-- extractor errors become logger_error records instead of being raised.
local json = _require("src.json")

local M = {}

local function errorRecord(hookName, err)
  return { event = "logger_error", hook = hookName, error = tostring(err) }
end

local function handler(deps, name, extractor)
  return function(...)
    local ok, record = pcall(extractor, deps.civ, ...)
    if ok and record == nil then return end
    if not ok then record = errorRecord(name, record) end
    deps.sink(json.encode(record))
  end
end

-- Extractors named in UpperCamelCase are GameEvents hooks; lowercase
-- names are helpers emitted explicitly (see docs/design-decisions.md).
function M.attach(deps)
  for name, extractor in pairs(deps.extractors) do
    if name:match("^%u") then
      deps.events[name].Add(handler(deps, name, extractor))
    end
  end
end

function M.emit(deps, name, extractor, ...)
  handler(deps, name, extractor)(...)
end

return M
end)

register("src.census", function()
-- Keeps a per-player city census between turns and emits city_destroyed
-- when a known city disappears. Razing fires no DLL hook (CvCity::
-- DoRazingTurn -> CvPlayer::disband contains no CallHook), so this is
-- polled once per player per turn via PlayerDoTurn rather than pushed
-- as an event. Registered directly on PlayerDoTurn (bypassing
-- logger.attach) since it needs cross-turn state and may emit zero or
-- more records per firing, unlike the one-hook-one-record extractors.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (census)", error = tostring(err) }
end

function M.new(civ, sink)
  local known = {}

  local function poll(playerId)
    local current = civ.citySet(playerId)
    for cityId, city in pairs(known[playerId] or {}) do
      if not current[cityId] then
        sink(json.encode({
          event = "city_destroyed",
          turn = civ.turn(),
          civ = civ.civName(playerId),
          city = city.name,
          x = city.x,
          y = city.y,
        }))
      end
    end
    known[playerId] = current
  end

  return function(playerId)
    local ok, err = pcall(poll, playerId)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.main", function()
-- Entry point: gate on the local opt-in flag, then wire the logger
-- to the real game. Receives the game globals as a table so tests
-- (and the in-game loader) decide what "real" means.
local adapter = _require("src.adapter")
local extractors = _require("src.extractors")
local logger = _require("src.logger")
local census = _require("src.census")

local M = {}

function M.enabled(modding)
  local data = modding.OpenUserData("civ-narrative-logger", 1)
  local value = data.GetValue("enabled")
  return value == 1 or value == "1"
end

function M.start(g)
  if not M.enabled(g.Modding) then return end
  local deps = {
    events = g.GameEvents,
    extractors = extractors,
    civ = adapter.new(g),
    sink = function(line) g.print("CIVLOG|" .. line) end,
  }
  logger.attach(deps)
  logger.emit(deps, "sessionStarted", extractors.sessionStarted)
  g.GameEvents.PlayerDoTurn.Add(census.new(deps.civ, deps.sink))
end

return M
end)

_require("src.main").start({
  Game = Game,
  Players = Players,
  Teams = Teams,
  Map = Map,
  GameInfo = GameInfo,
  GameDefines = GameDefines,
  PreGame = PreGame,
  GameEvents = GameEvents,
  Modding = Modding,
  print = print,
})
